import { gsap } from 'gsap';
import {
  Group,
  Mesh,
  BoxGeometry,
  PlaneGeometry,
  CircleGeometry,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
  PointLight,
  Color,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'journal-card-3';

  const inner = new Group();
  root.add(inner);

  // ---- dimensions (matches atlas rect aspect 512x320 = 1.6) ----
  const cardW = 1.8;
  const cardH = 1.125;
  const cardD = 0.07;

  // ---- accent bevel frame (behind, slightly larger, glows on hover/focus) ----
  const accentFrameGeo = new BoxGeometry(cardW + 0.14, cardH + 0.14, cardD * 0.6);
  const accentFrameMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.55,
    metalness: 0.4,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.0,
  });
  const accentFrame = new Mesh(accentFrameGeo, accentFrameMat);
  accentFrame.position.z = -0.04;
  inner.add(accentFrame);

  // ---- machined-metal ink frame (extruded bezel, bevel-ish via box) ----
  const frameGeo = new BoxGeometry(cardW + 0.06, cardH + 0.06, cardD);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.5,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const frame = new Mesh(frameGeo, frameMat);
  inner.add(frame);

  // ---- photo face ----
  const photoGeo = new PlaneGeometry(cardW, cardH);
  const photoMat = new MeshStandardNodeMaterial({
    color: new Color('#ffffff'),
    roughness: 0.6,
    metalness: 0.08,
  });
  const photo = new Mesh(photoGeo, photoMat);
  photo.position.z = cardD / 2 + 0.001;
  inner.add(photo);

  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (THREE.SRGBColorSpace) tex.colorSpace = THREE.SRGBColorSpace;
        photoMat.map = tex;
        photoMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // ---- stock badge chip (caption, bound to trpc.inventory.status.inStock) ----
  const chipW = 0.62;
  const chipH = 0.18;
  const chipGeo = new PlaneGeometry(chipW, chipH);
  const chipMat = new MeshBasicNodeMaterial({ color: new Color(colors.accent) });
  const chip = new Mesh(chipGeo, chipMat);
  chip.position.set(-cardW / 2 + chipW / 2 + 0.08, cardH / 2 - chipH / 2 - 0.08, cardD / 2 + 0.01);
  inner.add(chip);

  const badgeText = ctx.fontAtlas.createText('IN STOCK', {
    fontSize: 22,
    color: colors.paper,
    align: 'center',
    letterSpacingPx: 1.8,
  });
  badgeText.position.set(chip.position.x, chip.position.y, chip.position.z + 0.006);
  badgeText.scale.setScalar(0.0044);
  inner.add(badgeText);

  function setInStock(inStock, etaDays) {
    const label = inStock ? 'IN STOCK' : etaDays ? `ETA ${etaDays}D` : 'SOLD OUT';
    if (badgeText.userData?.setText) {
      badgeText.userData.setText(label);
    }
    chipMat.color = new Color(inStock ? colors.accent : colors.ink);
  }
  root.userData.setInStock = setInStock;
  root.userData.stockBadge = { chip, chipMat, badgeText };

  // ---- radial contact shadow ----
  const shadowGeo = new CircleGeometry(Math.max(cardW, cardH) * 0.78, 32);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    opacity: 0.45,
  });
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -cardH / 2 - 0.12, -cardD / 2 - 0.02);
  shadow.scale.set(1, 0.35, 1);
  inner.add(shadow);

  // ---- node-local accent rim + soft fill (scene provides ambient+key only) ----
  const rim = new PointLight(new Color(colors.accent), 0.9, 4, 2);
  rim.position.set(0.6, 0.4, 0.9);
  inner.add(rim);

  const fill = new PointLight(new Color(colors.paper), 0.35, 3, 2);
  fill.position.set(-0.6, -0.3, 1.2);
  inner.add(fill);

  // ---- motion ----
  const timelines = [];
  const baseY = inner.position.y;

  inner.scale.setScalar(0.94);
  const entrance = gsap.timeline();
  entrance.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' });
  timelines.push(entrance);

  const breathe = gsap.timeline({ repeat: -1, yoyo: true, delay: 0.9 });
  breathe.to(inner.scale, { x: 1.015, y: 1.015, z: 1.015, duration: 3.4, ease: 'sine.inOut' });
  timelines.push(breathe);

  let hovered = false;

  function hoverStart() {
    if (hovered) return;
    hovered = true;
    const tl = gsap.timeline();
    tl.to(inner.position, { y: baseY + 0.15, duration: 0.45, ease: 'power2.out' }, 0);
    tl.to(accentFrameMat, { emissiveIntensity: 1.0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function hoverEnd() {
    hovered = false;
    const tl = gsap.timeline();
    tl.to(inner.position, { y: baseY, duration: 0.4, ease: 'power2.out' }, 0);
    tl.to(accentFrameMat, { emissiveIntensity: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
    timelines.push(tl);
  }

  function pressDown() {
    const tl = gsap.timeline();
    tl.to(inner.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tl.to(inner.scale, { x: 1, y: 1, z: 1, duration: 0.25, ease: 'power2.out' });
    timelines.push(tl);
  }

  function handleClick() {
    pressDown();
    ctx.emit('hub-journal.select', { nodeId: config.id ?? 'journal-card-3' });
  }

  root.userData.handlers = {
    onHoverStart: hoverStart,
    onPointerEnter: hoverStart,
    onHoverEnd: hoverEnd,
    onPointerLeave: hoverEnd,
    onPointerDown: pressDown,
    onClick: handleClick,
  };

  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;

    [accentFrameGeo, frameGeo, photoGeo, chipGeo, shadowGeo].forEach((g) => g.dispose());
    [accentFrameMat, frameMat, photoMat, chipMat, shadowMat].forEach((m) => {
      if (m.map) m.map.dispose();
      m.dispose();
    });

    if (badgeText.geometry) badgeText.geometry.dispose?.();
    if (badgeText.material) badgeText.material.dispose?.();

    inner.remove(rim);
    inner.remove(fill);
  };

  return root;
}
